def _pathname_from(path: str) -> str:
    parsed = urlparse(path)
    return parsed.path or path


def _path_matches(pattern: str, pathname: str) -> bool:
    parts = []
    for segment in pattern.split("/"):
        if segment.startswith(":"):
            parts.append(r"[^/]+")
        elif segment == "*":
            parts.append(r".*")
        else:
            parts.append(re.escape(segment))
    return re.match("^" + "/".join(parts) + "$", pathname) is not None


def is_public_surface_path(method: str, path: str) -> bool:
    upper_method = method.upper()
    pathname = _pathname_from(path)
    return any(route_method == upper_method and _path_matches(route_path, pathname) for route_method, route_path in PUBLIC_SURFACE_ROUTES)
